-- =============================================================================
-- Add Brite UUID linkage to installers + one-time backfill from
-- the 2026-05-26 export (services/installers/install_company).
--
-- Brite (the upstream source of truth for installer company data) keys
-- records by UUID. The locator's installer_vendor_id matches Brite's
-- install_company.vendor_number, so we join on that and store the UUID
-- as a stable, cheap join key for the recurring 6-hour sync.
--
-- Idempotent: re-running the script is safe. The column add uses
-- IF NOT EXISTS, the staging table is dropped at the end, and the
-- UPDATE is matched on installer_vendor_id so it won't double-write.
-- =============================================================================

-- 1. Add the linkage columns (nullable for now; we'll know after the
--    backfill how many existing rows can't be matched).
ALTER TABLE public.installers
  ADD COLUMN IF NOT EXISTS brite_company_id uuid,
  ADD COLUMN IF NOT EXISTS brite_synced_at  timestamptz;

-- NOTE: NOT unique. The locator stores multiple "Location #N" rows per Brite
-- install_company (each physical service location is its own locator row),
-- so brite_company_id is many-to-one from locator -> Brite by design.
CREATE INDEX IF NOT EXISTS idx_installers_brite_company_id
  ON public.installers (brite_company_id)
  WHERE brite_company_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_installers_installer_vendor_id
  ON public.installers (installer_vendor_id)
  WHERE installer_vendor_id IS NOT NULL;

-- 2. Stage the export (745 rows from Brite installer_companies CSV).
DROP TABLE IF EXISTS _brite_companies_staging;
CREATE TEMP TABLE _brite_companies_staging (
  brite_company_id uuid    PRIMARY KEY,
  vendor_number    bigint  NOT NULL UNIQUE
);


-- 3. Backfill the link.
WITH updated AS (
  UPDATE public.installers i
     SET brite_company_id = s.brite_company_id
    FROM _brite_companies_staging s
   WHERE i.installer_vendor_id = s.vendor_number
     AND (i.brite_company_id IS NULL OR i.brite_company_id <> s.brite_company_id)
  RETURNING i.id
)
SELECT count(*) AS rows_linked FROM updated;

-- 4. Reconciliation report. Returns one row so you see it directly in
--    the Supabase SQL Editor result pane (RAISE NOTICE output isn't
--    always surfaced there).
SELECT
  (SELECT count(*) FROM _brite_companies_staging)                                 AS brite_export_rows,
  (SELECT count(*) FROM public.installers)                                        AS locator_total,
  (SELECT count(*) FROM public.installers
    WHERE installer_vendor_id IS NOT NULL)                                        AS locator_with_vendor_id,
  (SELECT count(*) FROM public.installers
    WHERE brite_company_id IS NOT NULL)                                           AS locator_linked_to_brite,
  (SELECT count(*) FROM public.installers
    WHERE installer_vendor_id IS NOT NULL AND brite_company_id IS NULL)           AS locator_unlinked_with_vendor_id,
  (SELECT count(*) FROM _brite_companies_staging s
     LEFT JOIN public.installers i ON i.installer_vendor_id = s.vendor_number
    WHERE i.id IS NULL)                                                           AS brite_rows_with_no_locator_match;

-- 5. Inspect (run separately AFTER the script finishes if you want
--    the actual unmatched lists; the temp table is dropped below).
--
--   -- Locator rows that have a vendor_number but did not match any
--   -- Brite UUID. These are likely legacy / inactive installers that
--   -- have aged out of Brite, or vendor_id typos.
--   SELECT i.id, i.name, i.installer_vendor_id
--     FROM public.installers i
--    WHERE i.installer_vendor_id IS NOT NULL
--      AND i.brite_company_id IS NULL
--    ORDER BY i.name;
--
--   -- Brite rows with no locator counterpart - new installers we
--   -- should create on first sync.
--   -- (Re-load _brite_companies_staging to run this query later.)

DROP TABLE IF EXISTS _brite_companies_staging;
